import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine } from '../src/invoices.js';

test('createInvoice creates a draft invoice with one line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  const inv = r.value;
  assert.equal(inv.customerId, 'C-001');
  assert.equal(inv.issueDate, '2026-10-07');
  assert.equal(inv.status, 'draft');
  assert.equal(inv.lines.length, 1);
  assert.equal(inv.lines[0].sku, 'DES-HOUR');
  assert.equal(inv.lines[0].name, 'Design work (hour)');
  assert.equal(inv.lines[0].qty, 5);
  assert.equal(inv.lines[0].unitPrice, 8500);
  assert.equal(inv.lines[0].vatRate, 21);
});

test('createInvoice creates invoices with multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[1].name, 'Development (hour)');
});

test('createInvoice reports CUSTOMER_NOT_FOUND for unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports DATE_INVALID for bad format', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '10-07-2026',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports DATE_INVALID for non-existent dates', () => {
  // February 30 doesn't exist
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-02-30',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports DATE_INVALID for invalid month', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-13-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports NO_LINES for empty array', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports QTY_INVALID for non-integer qty', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5.5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports QTY_INVALID for zero qty', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 0 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports QTY_INVALID for negative qty', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: -5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports UNKNOWN_SKU for invalid SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'NOPE', qty: 5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice stops at first error', () => {
  // Two lines, second has bad SKU
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'NOPE', qty: 3 },
    ],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 };
  assert.equal(lineTotal(line), 42500);
});

test('lineTotal handles various quantities', () => {
  const line1 = { sku: 'ICON-SET', qty: 10, unitPrice: 980, vatRate: 21 };
  assert.equal(lineTotal(line1), 9800);

  const line2 = { sku: 'STICKER', qty: 1000, unitPrice: 50, vatRate: 21 };
  assert.equal(lineTotal(line2), 50000);
});

test('invoiceTotals calculates subtotal and total for single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 42500, total: 42500 });
});

test('invoiceTotals calculates subtotal and total for multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 3, unitPrice: 9500, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 71000, total: 71000 });
});

test('addLine adds a new line to an invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;

  const r2 = addLine(inv, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  const inv2 = r2.value;
  assert.equal(inv2.lines.length, 2);
  assert.equal(inv2.lines[1].sku, 'DEV-HOUR');
  assert.equal(inv2.lines[1].qty, 3);
  assert.equal(inv2.lines[1].unitPrice, 9500);
});

test('addLine increases qty if SKU already exists', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;

  const r2 = addLine(inv, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  const inv2 = r2.value;
  assert.equal(inv2.lines.length, 1);
  assert.equal(inv2.lines[0].qty, 8);
});

test('addLine reports QTY_INVALID', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;

  const r2 = addLine(inv, { sku: 'DEV-HOUR', qty: 0 });
  assert.deepEqual(r2, { ok: false, error: 'QTY_INVALID' });
});

test('addLine reports UNKNOWN_SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;

  const r2 = addLine(inv, { sku: 'NOPE', qty: 1 });
  assert.deepEqual(r2, { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine reports NOT_DRAFT if status is not draft', () => {
  const inv = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const r = addLine(inv, { sku: 'DEV-HOUR', qty: 1 });
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine removes a line from an invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  const inv = r.value;

  const r2 = removeLine(inv, 'DES-HOUR');
  assert.equal(r2.ok, true);
  const inv2 = r2.value;
  assert.equal(inv2.lines.length, 1);
  assert.equal(inv2.lines[0].sku, 'DEV-HOUR');
});

test('removeLine reports LINE_NOT_FOUND', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;

  const r2 = removeLine(inv, 'NOPE');
  assert.deepEqual(r2, { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine reports NO_LINES if it would remove the last line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;

  const r2 = removeLine(inv, 'DES-HOUR');
  assert.deepEqual(r2, { ok: false, error: 'NO_LINES' });
});

test('removeLine reports NOT_DRAFT if status is not draft', () => {
  const inv = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [
      { sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', qty: 3, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 },
    ],
  };

  const r = removeLine(inv, 'DES-HOUR');
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('addLine and removeLine do not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;
  const originalLength = inv.lines.length;

  addLine(inv, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(inv.lines.length, originalLength);

  removeLine(inv, 'DES-HOUR');
  assert.equal(inv.lines.length, originalLength);
});

